3: export function loadGmaps(): Promise<void> {
4:   if (typeof window === 'undefined') return Promise.reject('no window');
5:   if ((window as any).google?.maps) return Promise.resolve();
6:   if (loadingPromise) return loadingPromise;
7:   loadingPromise = new Promise((resolve, reject) => {
8:     const s = document.createElement('script');
9:     s.src = 'https://maps.googleapis.com/maps/api/js?key=AIzaSyAz-iYhUlWrRAL7JiKm4rBYke3Oxah8trk&libraries=marker';
10:     s.async = true;
11:     s.onload = () => resolve();
12:     s.onerror = () => reject(new Error('Maps no cargó'));
13:     document.head.appendChild(s);
14:   });
15:   return loadingPromise;
16: }

